content.agent:alfworld/mlsb_planner/planner_work:
"""Worker process that hosts the (untrusted) policy and talks to the harness.

READ-ONLY. Launched by run_eval.py, one process per game, with stdin/stdout as
a JSON-lines channel and stderr as a log. The worker never touches the game
engine or the LLM server directly: every environment step goes through the
harness (which owns the environment and decides success), and every LLM
request is relayed through the harness, which meters the per-game budget and
holds the server credentials.

Protocol (one JSON object per line):
  harness -> worker : {"type": "init", task_type, seed, ...budget fields}
  harness -> worker : {"type": "reset", goal, obs, attempt, budget}
  harness -> worker : {"type": "act", obs, admissible, history, budget}
  harness -> worker : {"type": "attempt_finished", success, history, budget}
  harness -> worker : {"type": "shutdown"}
  worker -> harness : {"type": "llm", messages, max_tokens, temperature, stop, n}
  harness -> worker : {"type": "llm_result", texts: [..]}
  worker -> harness : {"type": "ready"} | {"type": "ok"} | {"type": "action", action}
                      | {"type": "error", message}

Anything the policy prints goes to stderr (sys.stdout is redirected before the
policy module is imported), so the protocol channel stays clean.

A single reader thread owns stdin and demultiplexes it: "llm_result" lines go to
the (one at a time) LLM caller, every other line is a command for the main loop.
A policy may therefore issue LLM calls from a helper thread of its own without
ever racing the command channel -- a command can never be swallowed by an LLM
caller, and an LLM reply can never surface as an unknown command.
"""
from __future__ import annotations

import json
import os
import queue
import sys
import threading
import traceback

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)

_OUT = sys.__stdout__
_IN = sys.__stdin__
sys.stdout = sys.stderr  # policy prints must not corrupt the protocol channel

from planner_api import Budget, LLMClient, RESTART  # noqa: E402

_EOF = object()
_commands: "queue.Queue[object]" = queue.Queue()
_llm_replies: "queue.Queue[object]" = queue.Queue()
_send_lock = threading.Lock()
_llm_lock = threading.Lock()


def _send(obj: dict) -> None:
    with _send_lock:      # one whole line per message, whichever thread sends it
        _OUT.write(json.dumps(obj) + "\n")
        _OUT.flush()


def _reader() -> None:
    while True:
        line = _IN.readline()
        if not line:
            _llm_replies.put(_EOF)
            _commands.put(_EOF)
            return
        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            _commands.put({"type": "_garbage", "line": line[:200]})
            continue
        if isinstance(msg, dict) and msg.get("type") == "llm_result":
            _llm_replies.put(msg)
        else:
            _commands.put(msg)


def _recv() -> dict:
    msg = _commands.get()
    if msg is _EOF:
        raise SystemExit(0)
    return msg


class _RPCLLMClient(LLMClient):
    def __init__(self) -> None:
        self._calls_left = 0

    def _rpc(self, req: dict) -> list[str]:
        with _llm_lock:   # one outstanding LLM request at a time; replies are FIFO
            _send(req)
            rep = _llm_replies.get()
        if rep is _EOF:
            raise SystemExit(0)
        self._calls_left = int(rep.get("calls_left", 0))
        return [str(t) for t in rep.get("texts", [])]

    def chat(self, messages, *, max_tokens=256, temperature=0.0, stop=None, n=1):
        return self._rpc({
            "type": "llm", "mode": "chat",
            "messages": [{"role": str(m.get("role", "user")), "content": str(m.get("content", ""))}
                         for m in messages],
            "max_tokens": int(max_tokens), "temperature": float(temperature),
            "stop": [str(s) for s in (stop or [])][:8], "n": int(n),
        })

    def complete(self, prompt, *, max_tokens=256, temperature=0.0, stop=None):
        out = self._rpc({
            "type": "llm", "mode": "complete", "prompt": str(prompt),
            "max_tokens": int(max_tokens), "temperature": float(temperature),
            "stop": [str(s) for s in (stop or [])][:8], "n": 1,
        })
        return out[0] if out else ""

    @property
    def calls_left(self) -> int:
        return self._calls_left


def _history(msg) -> list:
    return [(str(a), str(o)) for a, o in msg.get("history", [])]


def main() -> None:
    threading.Thread(target=_reader, name="rpc-reader", daemon=True).start()
    llm = _RPCLLMClient()
    planner = None
    while True:
        msg = _recv()
        t = msg.get("type")
        try:
            if t == "_garbage":
                _send({"type": "error", "message": f"protocol garbage: {msg.get('line')!r}"})
            elif t == "init":
                llm._calls_left = int(msg.get("max_llm_calls", 0)) - int(msg.get("llm_calls_used", 0))
                import custom_planner  # the editable module, imported only here
                planner = custom_planner.CustomPlanner(llm, str(msg["task_type"]), int(msg["seed"]))
                _send({"type": "ready"})
            elif t == "reset":
                planner.reset(str(msg["goal"]), str(msg["obs"]), int(msg["attempt"]),
                              Budget.from_dict(msg["budget"]))
                _send({"type": "ok"})
            elif t == "act":
                action = planner.act(str(msg["obs"]), [str(a) for a in msg.get("admissible", [])],
                                     _history(msg), Budget.from_dict(msg["budget"]))
                if not isinstance(action, str):
                    action = str(action)
                _send({"type": "action", "action": action.strip()[:200] or RESTART})
            elif t == "attempt_finished":
                planner.attempt_finished(bool(msg["success"]), _history(msg),
                                         Budget.from_dict(msg["budget"]))
                _send({"type": "ok"})
            elif t == "shutdown":
                _send({"type": "ok"})
                return
            else:
                _send({"type": "error", "message": f"unknown message type {t!r}"})
        except SystemExit:
            raise
        except BaseException as exc:  # noqa: BLE001 - report, do not die silently
            traceback.print_exc(file=sys.stderr)
            _send({"type": "error", "message": f"{type(exc).__name__}: {exc}"[:2000]})


if __name__ == "__main__":
    main()

