    return turns


def few_shot_messages(header: str, demos: list[str]) -> list[dict]:
    """[user: header] [assistant: OK] then the demonstrations' turns, in order."""
    messages = [{"role": "user", "content": header}, {"role": "assistant", "content": "OK"}]
    for i, demo in enumerate(demos):
        turns = transcript_to_turns(demo)
        if turns and turns[0]["role"] == "user":
            turns[0]["content"] = f"Example task {i + 1}:\n" + turns[0]["content"]
        messages.extend(turns)
    return messages


def merge_adjacent(messages: list[dict]) -> list[dict]:
    """Merge consecutive same-role turns (demo boundaries put two user turns in a row)."""
    out: list[dict] = []
    for m in messages:
        if out and out[-1]["role"] == m["role"]:
            out[-1] = {"role": m["role"], "content": out[-1]["content"] + "\n\n" + m["content"]}
        else:
            out.append(dict(m))
    return out


def parse_action(reply: str) -> str:
    """First non-empty line of the assistant reply, without a leading '>'."""
    for line in reply.splitlines():
        s = line.strip()
        if s:
            return s[1:].strip() if s.startswith(">") else s
    return ""
